":"application","topic":"Cell Discovery, Cell Theory and Common Features","fingerprint":"1344c28cef5d3e39e3bf4727c4b020252ac76585c318b8d24dc3b5a583d88fae","studyRef":{"sourceLabel":"BIO 111 General Biology I module, Study Session 4","sourceKind":"supplied_bio111_material","reviewedFromLocalFile":true,"databaseCourseCode":"BIO 101","sourceCourseCode":"BIO 111"},"generationMeta":{"import":"codex_bio101_from_bio111_300_v1","sourceReference":"BIO 111 General Biology I module, Study Session 4","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"bab0f600-707c-5cd9-8f30-6fb3440ca0b7","text":"Only cells can be seen without instruments","isCorrect":false,"position":0},{"id":"101328d2-adaf-58fb-abce-9f3d4a4d35fa","text":"Every cell is a complete multicellular organism","isCorrect":false,"position":1},{"id":"8f82b567-a72c-521a-9324-637137deb875","text":"Cells contain no chemical reactions","isCorrect":false,"position":2},{"id":"2fe13612-3520-5d43-a30e-5fd61a72f0a2","text":"Biochemical processes necessary for life occur within cells","isCorrect":true,"position":3}]},{"id":"87b8953d-3a36-5c03-9717-8e912d971304","position":70,"prompt":"Why does every cell require a plasma membrane?","explanation":"The membrane separates cellular contents while permitting controlled movement and communication.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Cell Discovery, Cell Theory and Common Features","fingerprint":"30b9e1d83dcf7c5dd37627ddb09dc1c0d230ccea2964ae5c5e8d45fefcbc7ce9","studyRef":{"sourceLabel":"BIO 111 General Biology I module, Study Session 4","sourceKind":"supplied_bio111_material","reviewedFromLocalFile":true,"databaseCourseCode":"BIO 101","sourceCourseCode":"BIO 111"},"generationMeta":{"import":"codex_bio101_from_bio111_300_v1","sourceReference":"BIO 111 General Biology I module, Study Session 4","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"7960a950-6de