enes are linked but sometimes separated by crossing over","isCorrect":true,"position":1},{"id":"465e3220-7e86-5dcb-9aad-b69a327edca9","text":"The genes are on different chromosomes and assort perfectly","isCorrect":false,"position":2},{"id":"9f8ec141-507f-56e3-9a6f-9ae010c2c2e0","text":"Meiosis did not occur","isCorrect":false,"position":3}]},{"id":"3f4816c7-373b-5f7d-b168-4e9e1f541805","position":260,"prompt":"Which life process ensures lineage continuity by producing new individuals?","explanation":"Reproduction produces offspring and continues a biological lineage.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Sexual and Asexual Reproduction","fingerprint":"fef2f94027da63db756540de2e369b947d8a2df7bb4bd34e7e08adfc2beec94e","studyRef":{"sourceLabel":"BIO 111 General Biology I module, Study Session 14","sourceKind":"supplied_bio111_material","reviewedFromLocalFile":true,"databaseCourseCode":"BIO 101","sourceCourseCode":"BIO 111"},"generationMeta":{"import":"codex_bio101_from_bio111_300_v1","sourceReference":"BIO 111 General Biology I module, Study Session 14","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"a8df1717-1c6f-55a3-89aa-b7c940be3560","text":"Reproduction","isCorrect":true,"position":0},{"id":"35bb571b-d668-5b41-a639-9d6e0c72edf2","text":"Excretion","isCorrect":false,"position":1},{"id":"74feaf16-fc3d-57ce-b98a-528c99f73b25","text":"Homeostasis","isCorrect":false,"position":2},{"id":"7ffda8af-ec29-5a25-8a0c-68d50276c2d7","text":"Classification","isCorrect":false,"position":3}]},{"id":"689d412c-dd94-5b0c-a891-fbb3571090bc","position":261,"prompt":"What defines asexual reproduction?","explanation":"Asexual reproduction uses one genetic source and often produces closely similar offspring.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Sexual and Asexual Reproduction","fingerprint":"5fc65efac8533d31479de5c9b2532bdd1539547749322fa59e20132a2fd388d2","studyRef":{