calFile":false,"databaseCourseCode":"BIO 101","sourceCourseCode":"BIO 111"},"generationMeta":{"import":"codex_bio101_from_bio111_300_v1","sourceReference":"General Biology I enrichment: Biological Interactions and Community Ecology","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"74070677-fe21-50e7-a5ed-0da01790347c","text":"The most numerous species by definition","isCorrect":false,"position":0},{"id":"f787d3fd-78cc-5984-b84d-638438a923c9","text":"A species with no interactions","isCorrect":false,"position":1},{"id":"1c69d968-af18-527c-abf6-6b674e3de1c8","text":"Any organism used in a laboratory","isCorrect":false,"position":2},{"id":"1076c80e-4b04-523e-a886-096cdc083473","text":"A species with an effect on community structure disproportionate to its abundance","isCorrect":true,"position":3}]},{"id":"859f0ac6-40a5-50be-a6f9-66dc145981fa","position":298,"prompt":"What is a trophic cascade?","explanation":"Changes in predators can propagate to herbivores and producers.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Biological Interactions and Community Ecology","fingerprint":"06578a73b9db68851b5a325b32c3aea2877028d51c389f01c5698f81d6113a90","studyRef":{"sourceLabel":"General Biology I enrichment: Biological Interactions and Community Ecology","sourceKind":"general_biology1","reviewedFromLocalFile":false,"databaseCourseCode":"BIO 101","sourceCourseCode":"BIO 111"},"generationMeta":{"import":"codex_bio101_from_bio111_300_v1","sourceReference":"General Biology I enrichment: Biological Interactions and Community Ecology","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"20ccdb7a-4a0c-5975-95f7-65d678df2551","text":"A type of genetic cross","isCorrect":false,"position":0},{"id":"4841bbfa-4278-5264-aacc-4b3b53fccd79","text":"A flow of water through one cell","isCorrect":false,"position":1},{"id":"ef371c4c-4f78-5c7e-b677-7edd6a9310f7","text":"A chain of indirect effects moving through feeding levels","isCorrect":true,"position":2},{"id":"314c706d-593e-54f4-8e18-2084693806d3","text":"A sequence of mitotic stages","isCorrect":false,"position":3}]},{"id":"94c198f5-a5b1-5c20-bd11-bee722ffb2fd","position":299,"prompt":"A relationship is beneficial when food is abundant but becomes competitive during drought. What does this show?","explanation":"Resource availability and other conditions can alter the costs and benefits experienced by partners.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Biological Interactions and Community Ecology","fingerprint":"475bb9aa3f0c384be1cb70221accf95439266058ec3b795c85e5232e4a792546","studyRef":{"sourceLabel":"General Biology I enrichment: Biological Interactions and Community Ecology","sourceKind":"general_biology1","reviewedFromLocalFile":false,"databaseCourseCode":"BIO 101","sourceCourseCode":"BIO 111"},"generationMeta":{"import":"codex_bio101_from_bio111_300_v1","sourceReference":"General Biology I enrichment: Biological Interactions and Community Ecology","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"3951854c-e9f9-5dea-97a1-1c5f4a3d3084","text":"Competition cannot occur within a community","isCorrect":false,"position":0},{"id":"984636ad-cbd1-5234-90bf-acef380aa829","text":"Interaction outcomes can depend on environmental context","isCorrect":true,"position":1},{"id":"2ead8f0e-8e95-5545-af6f-2f3e6b97a069","text":"Every interaction has a permanently fixed sign","isCorrect":false,"position":2},{"id":"f71c74be-1159-557b-b672-8ef09db450ef","text":"The species changed kingdoms","isCorrect":false,"position":3}]}]$bio101_questions$::jsonb)
  LOOP
    INSERT INTO public.study_quiz_questions
      (id, set_id, prompt, explanation, question_type, position, question_kind,
       difficulty_level, cognitive_level, source_topic, question_fingerprint,
       study_ref, generation_meta, ai_generated, published, created_at)
    VALUES
      ((v_question->>'id')::uuid, v_set_id, v_question->>'prompt', v_question->>'explanation',
       'mcq', (v_question->>'position')::integer, v_question->>'questionKind',
       v_question->>'difficulty', v_question->>'cognitive', v_question->>'topic',
       v_question->>'fingerprint', v_question->'studyRef', v_question->'generationMeta',
       false, true, now());

    FOR v_option IN
      SELECT value FROM jsonb_array_elements(v_question->'options')
    LOOP
      INSERT INTO public.study_quiz_options
        (id, question_id, text, is_correct, position, created_at)
      VALUES
        ((v_option->>'id')::uuid, (v_question->>'id')::uuid, v_option->>'text',
         (v_option->>'isCorrect')::boolean, (v_option->>'position')::integer, now());
    END LOOP;
  END LOOP;

  UPDATE public.study_quiz_sets
  SET questions_count = 300,
      exam_question_count = 40,
      time_limit_minutes = 40,
      published = false,
      visibility = 'private',
      updated_at = now()
  WHERE id = v_set_id;
END
$import$;

COMMIT;

-- Expected: 300 questions, 1200 options, 300 correct options, 0 verified before admin review.
SELECT
  s.id AS set_id,
  s.title,
  count(DISTINCT q.id) AS questions,
  count(o.id) AS options,
  count(o.id) FILTER (WHERE o.is_correct) AS correct_options,
  count(DISTINCT q.id) FILTER (WHERE q.exam_verified_at IS NOT NULL) AS verified_questions
FROM public.study_quiz_sets s
LEFT JOIN public.study_quiz_questions q ON coalesce(q.set_id, q.quiz_set_id) = s.id
LEFT JOIN public.study_quiz_options o ON o.question_id = q.id
WHERE upper(regexp_replace(coalesce(s.course_code, ''), '[^A-Za-z0-9]', '', 'g')) = 'BIO101'
  AND s.delivery_mode = 'mock_exam'
  AND s.exam_campaign_key = 'supplementary-2026'
GROUP BY s.id, s.title;
